function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function getTelegramContext(source) {
  const payload = source.payload || {};
  const message = source.message || payload.message || payload.body?.message || {};
  const chatId = source.chatId || message.chat?.id || payload.chatId || '';
  const rawText = String(source.rawText || source.text || message.text || message.caption || payload.text || '').trim();
  return { payload, message, chatId, rawText };
}

function cleanQuery(value) {
  return String(value || '')
    .trim()
    .replace(/^[\"'“”‘’]+|[\"'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

const source = $('Execute Workflow Trigger').item.json || {};
const ctx = getTelegramContext(source);
const raw = ctx.rawText;
const text = normalize(raw);
const prefixes = ['tim sheet', 'search sheet', 'tim bang tinh'];
let body = raw;
for (const prefix of prefixes) {
  if (text.startsWith(prefix + ' ')) {
    body = raw.slice(prefix.length + 1).trim();
    break;
  }
}

const query = cleanQuery(source.query || source.sheetName || source.fileName || body);
const limit = Number(source.limit || source.payload?.limit || 10) || 10;

return [{
  json: {
    ...source,
    payload: ctx.payload,
    message: ctx.message,
    chatId: ctx.chatId,
    rawText: raw,
    text,
    query,
    limit,
    hasTarget: Boolean(query),
    response: query ? '' : '📊 <b>Tim Google Sheet</b>\n\nVi du: <code>tim sheet Chi tieu</code>'
  }
}];

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;');
}

const source = $('Prepare Action').item.json || {};
const rows = $input.all().map((item) => item.json || {}).filter((item) => item.id || item.name);
const query = source.query || '';

let text = '🔎 <b>Ket qua tim Google Sheets</b>\n\n';
if (query) text += `Tu khoa: <i>${escapeHtml(query)}</i>\n\n`;

if (!rows.length) {
  text += query ? `Khong tim thay bang tinh phu hop voi: <i>${escapeHtml(query)}</i>` : 'Khong tim thay bang tinh phu hop.';
} else {
  rows.forEach((sheet, index) => {
    const name = sheet.name || 'Khong ro ten';
    const link = sheet.webViewLink || (sheet.id ? `https://docs.google.com/spreadsheets/d/${sheet.id}/edit` : '');
    const modified = sheet.modifiedTime ? new Date(sheet.modifiedTime).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false }) : '';
    text += `${index + 1}. 📊 `;
    text += link ? `<a href="${escapeHtml(link)}">${escapeHtml(name)}</a>\n` : `<b>${escapeHtml(name)}</b>\n`;
    if (modified) text += `   Sua luc: ${escapeHtml(modified)}\n`;
    if (sheet.id) text += `   ID: <code>${escapeHtml(sheet.id)}</code>\n`;
    text += '\n';
  });
}

return [{ json: { chatId: source.chatId, text: text.trim() } }];
